const defaultLimit = 100

type Server struct {
	pool           *pgxpool.Pool
	jobs           *river.Client[pgx.Tx]
	parser         parserv2.ParserServiceClient
	maxUploadBytes int64
	// Where the Gmail filter forwards statements; empty when the deployment has not set it.
	mailboxAddress string
}

func NewServer(pool *pgxpool.Pool, jobs *river.Client[pgx.Tx], parser parserv2.ParserServiceClient, maxUploadBytes int64, mailboxAddress string) *Server {
	return &Server{pool: pool, jobs: jobs, parser: parser, maxUploadBytes: maxUploadBytes, mailboxAddress: mailboxAddress}
}

var _ StrictServerInterface = (*Server)(nil)

// Register mounts the API. Use it instead of the generated RegisterHandlers, which would leave out
// notMultipartIsBadRequest.
func Register(router EchoRouter, server *Server) {
	RegisterHandlersWithOptions(router, NewStrictHandler(server, nil), RegisterHandlersOptions{
		OperationMiddlewares: map[string][]echo.MiddlewareFunc{"uploadDocument": {notMultipartIsBadRequest}},
	})
}

// notMultipartIsBadRequest answers an upload that is not a multipart form with the spec's 400. The
// generated handler opens the form before UploadDocument runs and returns that error as it is,
// which Echo would answer with a 500.
func notMultipartIsBadRequest(next echo.HandlerFunc) echo.HandlerFunc {
	return func(c *echo.Context) error {
		err := next(c)
		if errors.Is(err, http.ErrNotMultipart) || errors.Is(err, http.ErrMissingBoundary) {
			problem := UploadDocument400JSONResponse{ProblemJSONResponse{Message: err.Error()}}
			return problem.VisitUploadDocumentResponse(c.Response())
		}
		return err
	}
}

func (s *Server) UploadDocument(ctx context.Context, request UploadDocumentRequestObject) (UploadDocumentResponseObject, error) {
	file, err := readFilePart(request.Body, s.maxUploadBytes)
	switch {
	case errors.Is(err, errTooLarge):
		return UploadDocument413JSONResponse{Message: fmt.Sprintf("file is larger than %d MB", s.maxUploadBytes>>20)}, nil
	case errors.Is(err, errNotEmail):
		return UploadDocument415JSONResponse{Message: err.Error()}, nil
	case err != nil:
		//nolint:nilerr // a bad upload is a 400 response, not a handler failure
		return UploadDocument400JSONResponse{ProblemJSONResponse{Message: err.Error()}}, nil
	}

	sum := sha256.Sum256(file.data)
	var created bool
	var id int64
	err = pgx.BeginFunc(ctx, s.pool, func(tx pgx.Tx) error {
		row, err := dbq.New(tx).UpsertDocument(ctx, dbq.UpsertDocumentParams{
			Sha256:      sum[:],
			Filename:    file.name,
			ContentType: file.contentType,
			Content:     file.data,
		})
		if err != nil {
			return err
		}
		id, created = row.ID, row.Created
		if !created {
			return nil
		}
		// Enqueued in the same transaction: a stored document always has a parse job.
		_, err = s.jobs.InsertTx(ctx, tx, ingest.ParseDocumentArgs{DocumentID: id}, nil)
		return err
	})
	if err != nil {
		return nil, fmt.Errorf("store upload: %w", err)
	}

	doc, err := s.document(ctx, id)
	if err != nil {
		return nil, err
	}
	if created {
		return UploadDocument201JSONResponse(doc), nil
	}
	return UploadDocument200JSONResponse(doc), nil
}

func (s *Server) ListDocuments(ctx context.Context, request ListDocumentsRequestObject) (ListDocumentsResponseObject, error) {
	params := request.Params
	query := blankAsNil(params.Q)
	var states []string // nil, not empty: no state filter
	if params.State != nil {
		for _, state := range *params.State {
			states = append(states, string(state))
		}
	}
	queries := dbq.New(s.pool)
	rows, err := queries.ListDocuments(ctx, dbq.ListDocumentsParams{
		Before:   params.Before,
		States:   states,
		Ids:      ptrSlice(params.Id),
		Query:    query,
		RowLimit: limit(params.Limit),
	})
	if err != nil {
		return nil, fmt.Errorf("list documents: %w", err)
	}
	counts, err := queries.DocumentCounts(ctx, query)
	if err != nil {
		return nil, fmt.Errorf("count documents: %w", err)
	}

	page := DocumentPage{Items: make([]Document, 0, len(rows)), ByState: []StateCount{}}
	for _, row := range rows {
		page.Items = append(page.Items, toDocument(dbq.GetDocumentRow(row)))
	}
	byState := map[domain.DocumentStatus]int{}
	for _, row := range counts {
		byState[row.Status] = int(row.Documents)
	}
	for _, status := range domain.DocumentStatuses {
		if n := byState[status]; n > 0 {
			page.ByState = append(page.ByState, StateCount{State: DocumentStatus(status), Count: n})
		}
	}
	return ListDocuments200JSONResponse(page), nil
}

func (s *Server) GetDocument(ctx context.Context, request GetDocumentRequestObject) (GetDocumentResponseObject, error) {
	doc, err := s.document(ctx, request.Id)
	if errors.Is(err, pgx.ErrNoRows) {
		return GetDocument404JSONResponse{notFound("document", request.Id)}, nil
	}
	if err != nil {
		return nil, err
	}
	return GetDocument200JSONResponse(doc), nil
}

func (s *Server) ReparseDocument(ctx context.Context, request ReparseDocumentRequestObject) (ReparseDocumentResponseObject, error) {
	err := pgx.BeginFunc(ctx, s.pool, func(tx pgx.Tx) error {
		queries := dbq.New(tx)
		if _, err := queries.GetDocument(ctx, request.Id); err != nil {
			return err
		}
		if err := queries.MarkDocumentPending(ctx, request.Id); err != nil {
			return err
		}
		_, err := s.jobs.InsertTx(ctx, tx, ingest.ParseDocumentArgs{DocumentID: request.Id}, nil)
		return err
	})
	if errors.Is(err, pgx.ErrNoRows) {
		return ReparseDocument404JSONResponse{notFound("document", request.Id)}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("queue re-parse: %w", err)
	}
	doc, err := s.document(ctx, request.Id)
	if err != nil {
		return nil, err
	}
	return ReparseDocument202JSONResponse(doc), nil
}

// DeleteDocument deletes a document that holds nothing of the ledger, such as a file uploaded by mistake
// or a mail no parser takes, so it does not stay among the documents for good.
func (s *Server) DeleteDocument(ctx context.Context, request DeleteDocumentRequestObject) (DeleteDocumentResponseObject, error) {
	var status domain.DocumentStatus
	err := pgx.BeginFunc(ctx, s.pool, func(tx pgx.Tx) error {
		queries := dbq.New(tx)
		var err error
		// Locked, so that a retry or a re-parse cannot start on it between the check and the delete.
		if status, err = queries.LockDocument(ctx, request.Id); err != nil || !status.Deletable() {
			return err
		}
		// A document that names this one as holding its statement would be left a duplicate of nothing,
		// with the statement in no one's hands. Parsed again, one of them holds it. Before the delete,
		// which forgets which documents those were.
		duplicates, err := queries.MarkDuplicatesPending(ctx, request.Id)
		if err != nil {
			return fmt.Errorf("duplicates of it: %w", err)
		}
		for _, id := range duplicates {
			if _, err := s.jobs.InsertTx(ctx, tx, ingest.ParseDocumentArgs{DocumentID: id}, nil); err != nil {
				return fmt.Errorf("queue document %d: %w", id, err)
			}
		}
		return queries.DeleteDocument(ctx, request.Id)
	})
	if errors.Is(err, pgx.ErrNoRows) {
		return DeleteDocument404JSONResponse{notFound("document", request.Id)}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("delete document %d: %w", request.Id, err)
	}
	switch {
	case status == domain.Pending:
		return DeleteDocument409JSONResponse{Message: fmt.Sprintf("document %d is being parsed: delete it once that is done", request.Id)}, nil
	case !status.Deletable():
		return DeleteDocument409JSONResponse{Message: fmt.Sprintf("document %d holds a statement: only one that failed, was skipped, or is a duplicate can be deleted", request.Id)}, nil
	}
	return DeleteDocument204Response{}, nil
}

func (s *Server) GetDocumentContent(ctx context.Context, request GetDocumentContentRequestObject) (GetDocumentContentResponseObject, error) {
	row, err := dbq.New(s.pool).GetDocumentContent(ctx, request.Id)
	if errors.Is(err, pgx.ErrNoRows) {
		return GetDocumentContent404JSONResponse{notFound("document", request.Id)}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("get document %d content: %w", request.Id, err)
	}
	served := serveFile(row.ContentType, row.Filename)
	return GetDocumentContent200AsteriskResponse{
		Body:          bytes.NewReader(row.Content),
		ContentType:   served.contentType,
		ContentLength: int64(len(row.Content)),
		Headers: GetDocumentContent200ResponseHeaders{
			ContentDisposition:  &served.disposition,
			XContentTypeOptions: &served.nosniff,
		},
	}, nil
}

type servedFile struct {
	contentType, disposition, nosniff string
}

// serveFile decides how an original or an opened file is sent. It comes from the app's own origin,
// so only a PDF may open in place; anything else downloads as application/octet-stream, whatever it
// claims to be, and nosniff stops the browser from guessing its way to HTML.
func serveFile(contentType, filename string) servedFile {
	served := servedFile{contentType: contentTypeOther, disposition: "attachment", nosniff: "nosniff"}
	if contentType == contentTypePDF {
		served.contentType, served.disposition = contentTypePDF, "inline"
	}
	served.disposition = mime.FormatMediaType(served.disposition, map[string]string{"filename": filename})
	return served
}

func (s *Server) ListStatements(ctx context.Context, request ListStatementsRequestObject) (ListStatementsResponseObject, error) {
	queries := dbq.New(s.pool)
	rows, err := queries.ListStatements(ctx, limit(request.Params.Limit))
	if err != nil {
		return nil, fmt.Errorf("list statements: %w", err)
	}
	ids := make([]int64, 0, len(rows))
	for _, row := range rows {
		ids = append(ids, row.ID)
	}
	checks, err := statementChecks(ctx, queries, ids)
	if err != nil {
		return nil, err
	}
	statements := make(ListStatements200JSONResponse, 0, len(rows))
	for _, row := range rows {
		statements = append(statements, toStatement(row, checks[row.ID]))
	}
	return statements, nil
}

func (s *Server) GetStatement(ctx context.Context, request GetStatementRequestObject) (GetStatementResponseObject, error) {
	queries := dbq.New(s.pool)
	row, err := queries.GetStatement(ctx, request.Id)
	if errors.Is(err, pgx.ErrNoRows) {
		return GetStatement404JSONResponse{notFound("statement", request.Id)}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("get statement %d: %w", request.Id, err)
	}
	checks, err := statementChecks(ctx, queries, []int64{row.ID})
	if err != nil {
		return nil, err
	}
	return GetStatement200JSONResponse(toStatement(dbq.ListStatementsRow(row), checks[row.ID])), nil
}

// statementChecks are the statements' checks (ADR 0021), by statement, each's in order.
func statementChecks(ctx context.Context, queries *dbq.Queries, ids []int64) (map[int64][]Check, error) {
	rows, err := queries.StatementChecks(ctx, ids)
	if err != nil {
		return nil, fmt.Errorf("statement checks: %w", err)
	}
	checks := map[int64][]Check{}
	for _, r := range rows {
		checks[r.StatementID] = append(checks[r.StatementID], Check{
			Name: r.Name, Unit: r.Unit, Computed: numeric.String(r.Computed), Stated: numeric.String(r.Stated), Balanced: r.Balanced,
		})
	}
	return checks, nil
}

func (s *Server) ListStatementTransactions(ctx context.Context, request ListStatementTransactionsRequestObject) (ListStatementTransactionsResponseObject, error) {
	queries := dbq.New(s.pool)
	exists, err := queries.StatementExists(ctx, request.Id)
	if err != nil {
		return nil, fmt.Errorf("find statement: %w", err)
	}
	if !exists {
		return ListStatementTransactions404JSONResponse{notFound("statement", request.Id)}, nil
	}
	rows, err := queries.ListTransactions(ctx, request.Id)
	if err != nil {
		return nil, fmt.Errorf("list transactions: %w", err)
	}
	transactions := make(ListStatementTransactions200JSONResponse, 0, len(rows))
	for _, row := range rows {
		tx, err := toTransaction(row)
		if err != nil {
			return nil, err
		}
		transactions = append(transactions, tx)
	}
	return transactions, nil
}

func (s *Server) GetTransaction(ctx context.Context, request GetTransactionRequestObject) (GetTransactionResponseObject, error) {
	rows, err := dbq.New(s.pool).TransactionFamily(ctx, request.Id)
	if err != nil {
		return nil, fmt.Errorf("get transaction %d: %w", request.Id, err)
	}
	family := TransactionFamily{Children: []Transaction{}}
	found := false
	for _, row := range rows {
		tx, err := toTransaction(dbq.ListTransactionsRow(row))
		if err != nil {
			return nil, err
		}
		switch {
		case tx.Id == request.Id:
			family.Transaction, found = tx, true
		case tx.Parent != nil && tx.Parent.Id == request.Id:
			family.Children = append(family.Children, tx)
		default:
			family.Parent = &tx
		}
	}
	if !found {
		return GetTransaction404JSONResponse{notFound("transaction", request.Id)}, nil
	}
	return GetTransaction200JSONResponse(family), nil
}

func (s *Server) document(ctx context.Context, id int64) (Document, error) {
	row, err := dbq.New(s.pool).GetDocument(ctx, id)
	if err != nil {
		return Document{}, fmt.Errorf("get document %d: %w", id, err)
	}
	return toDocument(row), nil
}

type upload struct {
	name        string
	contentType string
	data        []byte
}

var errTooLarge = errors.New("file too large")

func readFilePart(reader *multipart.Reader, maxBytes int64) (upload, error) {
	for {
		part, err := reader.NextPart()
		if errors.Is(err, io.EOF) {
			return upload{}, errors.New(`form field "file" is missing`)
		}
		if err != nil {
			return upload{}, fmt.Errorf("read form: %w", err)
		}
		if part.FormName() != "file" {
			continue
		}
		data, err := io.ReadAll(io.LimitReader(part, maxBytes+1))
		if err != nil {
			return upload{}, fmt.Errorf("read file: %w", err)
		}
		if int64(len(data)) > maxBytes {
			return upload{}, errTooLarge
		}
		if len(data) == 0 {
			return upload{}, errors.New("file is empty")
		}
		if !isEmail(data) {
			return upload{}, errNotEmail
		}
		return upload{name: filepath.Base(part.FileName()), contentType: contentTypeEmail, data: data}, nil
	}
}

var errNotEmail = errors.New("only statement e-mails (.eml) can be uploaded, never a bare PDF (ADR 0014)")

// isEmail reports whether data reads as an e-mail: a header block net/mail accepts. The stored type
// is decided by this, never by what the browser declares: the original is served back from the
// app's origin, where a stored "text/html" or "image/svg+xml" would run.
func isEmail(data []byte) bool {
	if bytes.HasPrefix(data, []byte("%PDF")) {
		return false
	}
	message, err := mail.ReadMessage(bytes.NewReader(data))
	return err == nil && len(message.Header) > 0
}

const (
	contentTypePDF   = "application/pdf"
	contentTypeEmail = "message/rfc822"
	contentTypeOther = "application/octet-stream"
)

func limit(requested *Limit) int32 {
	if requested == nil {
		return defaultLimit
	}
	// The spec allows 1-500, but the generated handlers do not enforce it.
	return int32(min(max(*requested, 1), 500)) //nolint:gosec // clamped above
}

// clamp applies a query parameter's default and range, which the generated handlers do not enforce.
func clamp(requested *int, fallback, lo, hi int) int32 {
	if requested == nil {
		return int32(fallback) //nolint:gosec // a small constant
	}
	return int32(min(max(*requested, lo), hi)) //nolint:gosec // clamped to hi, at most MaxInt32
}

func date(d *openapi_types.Date) pgtype.Date {
	if d == nil {
		return pgtype.Date{}
	}
	return pgtype.Date{Time: d.Time, Valid: true}
}

func blankAsNil(s *string) *string {
	if s == nil || strings.TrimSpace(*s) == "" {
		return nil
	}
	trimmed := strings.TrimSpace(*s)
	return &trimmed
}

func notFound(what string, id int64) ProblemJSONResponse {
	return ProblemJSONResponse{Message: fmt.Sprintf("%s %d not found", what, id)}
}

// ptrSlice is a repeatable query parameter's values; nil, no filter, when it is absent.
func ptrSlice[T any](values *[]T) []T {
	if values == nil {
		return nil
	}
	return *values
}
